from unittest import TestCase

class TestMergeDicts(TestCase):
    def test_positive(self):
        dict_a = {'a': 1, 'b': 2}
        dict_b = {'c': 3, 'd': 4}
        expected = {'a': 1, 'b': 2, 'c': 3, 'd': 4}
        self.assertEqual(merge_dicts(dict_a, dict_b), expected)

    def test_empty_dicts(self):
        self.assertEqual(merge_dicts({}, {}), {})

    def test_one_empty_dict(self):
        self.assertEqual(merge_dicts({'x': 1}, {}), {'x': 1})
        self.assertEqual(merge_dicts({}, {'y': 2}), {'y': 2})

    def test_conflicting_keys(self):
        with self.assertRaises(TypeError):
            merge_dicts({'x': 1}, {'x': 2})

    def test_non_dict_input(self):
        with self.assertRaises(TypeError):
            merge_dicts('not a dict', {'y': 2})
        with self.assertRaises(TypeError):
            merge_dicts({'x': 1}, ['z'])
